import 'dotenv/config';
import express from 'express';
import cookieParser from 'cookie-parser';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import multer from 'multer';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import nodemailer from 'nodemailer';
import QRCode from 'qrcode';
import db from './db.js';

const app=express();
app.disable('x-powered-by');
app.use(helmet({contentSecurityPolicy:false,crossOriginEmbedderPolicy:false}));
app.set('trust proxy', 1);
app.use((req,res,next)=>{res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');res.setHeader('Permissions-Policy','geolocation=(), microphone=(), camera=()');next();});
const PORT=Number(process.env.PORT||3000); const JWT_SECRET=process.env.JWT_SECRET||'dev-secret-change-me';
const uploadDir=path.resolve('uploads'); fs.mkdirSync(uploadDir,{recursive:true});
app.use(express.json({limit:'2mb'})); app.use(express.urlencoded({extended:true})); app.use(cookieParser());
app.use('/uploads',express.static(uploadDir)); app.use(express.static(path.resolve('public')));

const allowedMime=new Set(['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/jpeg','image/png','image/webp']);
const requestUpload=multer({storage:multer.diskStorage({destination:uploadDir,filename:(req,file,cb)=>cb(null,'request-'+Date.now()+'-'+randomUUID()+path.extname(file.originalname).toLowerCase())}),fileFilter:(req,file,cb)=>cb(null,allowedMime.has(file.mimetype)),limits:{fileSize:Number(process.env.MAX_REQUEST_FILE_MB||10)*1024*1024}});
const upload=multer({storage:multer.diskStorage({destination:uploadDir,filename:(req,file,cb)=>cb(null,Date.now()+'-'+randomUUID()+path.extname(file.originalname).toLowerCase())}),fileFilter:(req,file,cb)=>cb(null,allowedMime.has(file.mimetype)),limits:{fileSize:Number(process.env.MAX_UPLOAD_MB||20)*1024*1024}});
const loginLimiter=rateLimit({windowMs:15*60*1000,max:10,standardHeaders:true,legacyHeaders:false,message:{error:'ብዙ የመግቢያ ሙከራዎች ተደርገዋል። እባክዎ ቆይተው ይሞክሩ።'}});
const aiLimiter=rateLimit({windowMs:60*1000,max:20,standardHeaders:true,legacyHeaders:false,message:{error:'AI ጥያቄ ገደብ ደርሷል።'}});
function auth(req,res,next){try{const t=req.cookies.mesob_admin||''; req.admin=jwt.verify(t,JWT_SECRET); const a=db.prepare('SELECT id,email,full_name,role,institution_id,active FROM admins WHERE id=?').get(req.admin.id); if(!a||!a.active)return res.status(401).json({error:'Account disabled'}); req.admin=a; next();}catch{res.status(401).json({error:'Unauthorized'});}}
function requireRole(...roles){return (req,res,next)=>{if(roles.includes(req.admin.role)||req.admin.role==='superadmin')return next();res.status(403).json({error:'ይህን ክዋኔ ለማድረግ ፈቃድ የለዎትም።'});};}
function scopeRequests(req,res,next){if(req.admin.role==='office_staff' && req.admin.institution_id) req.officeScope=req.admin.institution_id; next();}
function signAdmin(a){return jwt.sign({id:a.id,email:a.email,role:a.role||'superadmin',institution_id:a.institution_id||null,full_name:a.full_name||''},JWT_SECRET,{expiresIn:'8h'});}
function signCitizen(c){return jwt.sign({id:c.id,phone:c.phone},JWT_SECRET,{expiresIn:'7d'});}
function citizenAuth(req,res,next){try{const t=req.cookies.mesob_citizen||''; req.citizen=jwt.verify(t,JWT_SECRET); next();}catch{res.status(401).json({error:'Citizen authentication required'});}}
function notificationConfig(){return {email:process.env.SMTP_HOST&&process.env.SMTP_USER&&process.env.SMTP_PASS,sms:!!process.env.SMS_WEBHOOK_URL};}
function makeMailer(){if(!notificationConfig().email)return null;return nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:String(process.env.SMTP_SECURE||'false')==='true',auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}});}
async function dispatchNotification(id){const n=db.prepare('SELECT n.*, c.email citizen_email, c.full_name FROM notifications n LEFT JOIN citizens c ON c.id=n.citizen_id WHERE n.id=?').get(id);if(!n||n.status!=='Queued')return;try{if(n.channel==='email'){const mailer=makeMailer();if(!mailer||!n.citizen_email){db.prepare("UPDATE notifications SET status='Skipped' WHERE id=?").run(id);return;}await mailer.sendMail({from:process.env.SMTP_FROM||process.env.SMTP_USER,to:n.citizen_email,subject:'የእነዋሪ ከተማ ዲጂታል መሶብ — የጥያቄ ሁኔታ',text:n.message});db.prepare("UPDATE notifications SET status='Sent' WHERE id=?").run(id);}else if(n.channel==='sms'){if(!process.env.SMS_WEBHOOK_URL){db.prepare("UPDATE notifications SET status='Skipped' WHERE id=?").run(id);return;}const r=await fetch(process.env.SMS_WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/json',...(process.env.SMS_WEBHOOK_TOKEN?{Authorization:`Bearer ${process.env.SMS_WEBHOOK_TOKEN}`}:{})},body:JSON.stringify({to:n.recipient,message:n.message,reference:n.request_id})});db.prepare("UPDATE notifications SET status=? WHERE id=?").run(r.ok?'Sent':'Failed',id);} }catch(e){db.prepare("UPDATE notifications SET status='Failed' WHERE id=?").run(id);}}
function queueCitizenNotifications(requestId,citizenId,phone,message){const c=db.prepare('SELECT email FROM citizens WHERE id=?').get(citizenId);const ids=[];if(phone)ids.push(db.prepare("INSERT INTO notifications(request_id,citizen_id,channel,recipient,message) VALUES(?,?,?,?,?)").run(requestId,citizenId,'sms',phone,message).lastInsertRowid);if(c?.email)ids.push(db.prepare("INSERT INTO notifications(request_id,citizen_id,channel,recipient,message) VALUES(?,?,?,?,?)").run(requestId,citizenId,'email',c.email,message).lastInsertRowid);return ids;}
function crud(table,fields,writeRoles=['admin','editor']){
 app.get('/api/admin/'+table,auth,(req,res)=>res.json(db.prepare(`SELECT * FROM ${table} ORDER BY id DESC`).all()));
 app.post('/api/admin/'+table,auth,requireRole(...writeRoles),(req,res)=>{const vals=fields.map(f=>req.body[f]??''); const q=`INSERT INTO ${table}(${fields.join(',')}) VALUES(${fields.map(()=>'?').join(',')})`; const r=db.prepare(q).run(...vals); res.json({id:r.lastInsertRowid});});
 app.put('/api/admin/'+table+'/:id',auth,requireRole(...writeRoles),(req,res)=>{const set=fields.map(f=>`${f}=?`).join(','); const vals=fields.map(f=>req.body[f]??''); db.prepare(`UPDATE ${table} SET ${set}, updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(...vals,req.params.id); res.json({ok:true});});
 app.delete('/api/admin/'+table+'/:id',auth,requireRole(...writeRoles),(req,res)=>{db.prepare(`DELETE FROM ${table} WHERE id=?`).run(req.params.id);res.json({ok:true});});
}
app.post('/api/auth/login',loginLimiter,(req,res)=>{const {email,password}=req.body; const a=db.prepare('SELECT * FROM admins WHERE email=? AND active=1').get(email); if(!a||!bcrypt.compareSync(password,a.password_hash))return res.status(401).json({error:'የመግቢያ መረጃ ትክክል አይደለም'}); db.prepare('UPDATE admins SET last_login_at=CURRENT_TIMESTAMP WHERE id=?').run(a.id); res.cookie('mesob_admin',signAdmin(a),{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production',maxAge:8*3600*1000});res.json({ok:true,admin:{id:a.id,email:a.email,full_name:a.full_name,role:a.role,institution_id:a.institution_id}});});
app.post('/api/auth/logout',(req,res)=>{res.clearCookie('mesob_admin');res.json({ok:true})});
app.get('/api/auth/me',auth,(req,res)=>res.json(req.admin));
