app.post('/api/admin/staff',auth,requireRole('superadmin','admin'),(req,res)=>{const email=String(req.body.email||'').trim(),fullName=String(req.body.full_name||'').trim(),password=String(req.body.password||''),role=String(req.body.role||'viewer'),institutionId=Number(req.body.institution_id)||null;const roles=new Set(['admin','editor','office_staff','viewer']);if(!email||!fullName||password.length<10||!roles.has(role))return res.status(400).json({error:'Email፣ ስም፣ 10+ ቁምፊ የይለፍ ቃል እና ትክክለኛ role ያስገቡ።'});if(role==='office_staff'&&!institutionId)return res.status(400).json({error:'Office staff ለመፍጠር ፅ/ቤት ይምረጡ።'});if(db.prepare('SELECT id FROM admins WHERE email=?').get(email))return res.status(409).json({error:'ይህ email ቀድሞ ተመዝግቧል።'});const r=db.prepare('INSERT INTO admins(email,password_hash,full_name,role,institution_id,active) VALUES(?,?,?,?,?,1)').run(email,bcrypt.hashSync(password,12),fullName,role,institutionId);res.status(201).json({id:r.lastInsertRowid});});
