function parseService(row){
 let schema=[]; try{schema=JSON.parse(row.form_schema||'[]')}catch{}
 let workflow=[]; try{workflow=JSON.parse(row.workflow_schema||'[]')}catch{}
 return {key:row.service_key,am:row.name_am,en:row.name_en,description_am:row.description_am,description_en:row.description_en,officeId:row.institution_id,fee:Number(row.fee||0),currency:row.currency||'ETB',estimated_days:Number(row.estimated_days||3),required_documents:(row.required_documents||'').split(',').map(x=>x.trim()).filter(Boolean),form_schema:schema,workflow_schema:workflow,payment_required:Number(row.fee||0)>0};
}
function getService(key){const row=db.prepare('SELECT * FROM office_services WHERE service_key=? AND active=1').get(key);return row?parseService(row):null;}

function safeWorkflow(input){try{const a=Array.isArray(input)?input:JSON.parse(input||'[]');const seen=new Set();return a.slice(0,20).map((x,i)=>{const key=String(x.key||`step-${i+1}`).toLowerCase().replace(/[^a-z0-9_-]/g,'-').slice(0,40);return {key,name_am:String(x.name_am||'').slice(0,120),name_en:String(x.name_en||'').slice(0,120),status:['Received','In Review','In Progress','Completed','Rejected'].includes(x.status)?x.status:'In Progress',role:String(x.role||'').slice(0,80),terminal:!!x.terminal,order:i+1}}).filter(x=>x.key&&x.name_am&&x.name_en&&!seen.has(x.key)&&seen.add(x.key))}catch{return []}}
function workflowForRequest(r){let a=[];try{a=JSON.parse(r.workflow_schema_snapshot||'[]')}catch{}return a}
function safeSchema(input){try{const a=Array.isArray(input)?input:JSON.parse(input||'[]');return a.slice(0,20).map(x=>({name:String(x.name||'').replace(/[^a-zA-Z0-9_]/g,'').slice(0,40),label_am:String(x.label_am||'').slice(0,120),label_en:String(x.label_en||'').slice(0,120),type:['text','number','date','email','tel','textarea','select'].includes(x.type)?x.type:'text',required:!!x.required,options:Array.isArray(x.options)?x.options.slice(0,20).map(v=>String(v).slice(0,100)):[]})).filter(x=>x.name&&x.label_am&&x.label_en)}catch{return []}}
const requestLimiter=rateLimit({windowMs:10*60*1000,max:12,standardHeaders:true,legacyHeaders:false,message:{error:'በጣም ብዙ ጥያቄዎች ተልከዋል። እባክዎ ቆይተው ይሞክሩ።'}});
function makeRef(){return 'ENW-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,7).toUpperCase();}
app.get('/api/public/certificates/verify',(req,res)=>{const code=String(req.query.code||'').trim().toUpperCase();if(!code)return res.status(400).json({error:'Verification code is required'});const c=db.prepare('SELECT certificate_no,verification_code,title_am,title_en,holder_name,service_name_am,service_name_en,issued_by,issued_at,expires_at,status,notes FROM certificates WHERE verification_code=?').get(code);if(!c)return res.status(404).json({valid:false,error:'የማረጋገጫ ኮዱ አልተገኘም።'});const expired=c.expires_at && new Date(c.expires_at)<new Date();res.json({valid:c.status==='Valid'&&!expired,expired,...c});});
app.get('/api/public/certificates/qr',(req,res)=>{const code=String(req.query.code||'').trim().toUpperCase();if(!code)return res.status(400).send('Missing code');res.setHeader('Cache-Control','public,max-age=3600');QRCode.toDataURL(`${req.protocol}://${req.get('host')}/verify.html?code=${encodeURIComponent(code)}`,{width:420,margin:2,errorCorrectionLevel:'M'}).then(data=>res.json({data,verify_url:`${req.protocol}://${req.get('host')}/verify.html?code=${encodeURIComponent(code)}`})).catch(()=>res.status(500).json({error:'QR generation failed'}));});
app.get('/api/admin/certificates',auth,requireRole('superadmin','admin','viewer','editor'),(req,res)=>{const rows=db.prepare('SELECT c.*,r.reference_no request_reference FROM certificates c LEFT JOIN service_requests r ON r.id=c.request_id ORDER BY c.id DESC LIMIT 500').all();res.json(rows);});
app.post('/api/admin/certificates',auth,requireRole('superadmin','admin','editor'),(req,res)=>{const requestId=Number(req.body.request_id||0)||null;const r=requestId?db.prepare('SELECT * FROM service_requests WHERE id=?').get(requestId):null;if(requestId&&!r)return res.status(404).json({error:'Request not found'});const holder=String(req.body.holder_name||r?.full_name||'').trim();const titleAm=String(req.body.title_am||'የማረጋገጫ ሰነድ').trim();const titleEn=String(req.body.title_en||'Official Certificate').trim();if(holder.length<2)return res.status(400).json({error:'Holder name is required'});const certNo='ECA-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-7);const code=randomUUID().replaceAll('-','').slice(0,20).toUpperCase();const serviceAm=String(req.body.service_name_am||r?.service_name_am||'').trim();const serviceEn=String(req.body.service_name_en||r?.service_name_en||'').trim();const issuedBy=String(req.body.issued_by||'Enewari City Administration').trim();const expiresAt=String(req.body.expires_at||'').trim();const notes=String(req.body.notes||'').slice(0,1000);const result=db.prepare('INSERT INTO certificates(certificate_no,verification_code,request_id,citizen_id,title_am,title_en,holder_name,service_name_am,service_name_en,issued_by,expires_at,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').run(certNo,code,requestId,r?.citizen_id||null,titleAm,titleEn,holder,serviceAm,serviceEn,issuedBy,expiresAt,'Valid',notes);res.status(201).json({id:result.lastInsertRowid,certificate_no:certNo,verification_code:code,verify_url:'/verify.html?code='+code});});
app.put('/api/admin/certificates/:id',auth,requireRole('superadmin','admin','editor'),(req,res)=>{const status=['Valid','Revoked','Expired'].includes(req.body.status)?req.body.status:'Valid';db.prepare('UPDATE certificates SET status=?,notes=?,expires_at=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,String(req.body.notes||'').slice(0,1000),String(req.body.expires_at||''),req.params.id);res.json({ok:true});});

