app.post('/api/admin/services',auth,requireRole('superadmin','admin','editor'),(req,res)=>{const key=String(req.body.service_key||'').trim().toLowerCase().replace(/[^a-z0-9_-]/g,'-');const institutionId=Number(req.body.institution_id);if(!key||!institutionId||!String(req.body.name_am||'').trim()||!String(req.body.name_en||'').trim())return res.status(400).json({error:'የአገልግሎት መለያ፣ ስም እና ፅ/ቤት ያስፈልጋል።'});try{const r=db.prepare('INSERT INTO office_services(institution_id,service_key,name_am,name_en,description_am,description_en,fee,currency,estimated_days,required_documents,form_schema,workflow_schema,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').run(institutionId,key,String(req.body.name_am).trim(),String(req.body.name_en).trim(),String(req.body.description_am||''),String(req.body.description_en||''),Math.max(0,Number(req.body.fee||0)),String(req.body.currency||'ETB').slice(0,8),Math.max(0,Number(req.body.estimated_days||3)),String(req.body.required_documents||'').slice(0,1000),JSON.stringify(safeSchema(req.body.form_schema)),JSON.stringify(safeWorkflow(req.body.workflow_schema)),req.body.active===0?0:1);res.status(201).json({id:r.lastInsertRowid});}catch(e){res.status(409).json({error:'ይህ service key አስቀድሞ አለ።'});}});
app.put('/api/admin/services/:id',auth,requireRole('superadmin','admin','editor'),(req,res)=>{const old=db.prepare('SELECT * FROM office_services WHERE id=?').get(req.params.id);if(!old)return res.status(404).json({error:'Not found'});const institutionId=Number(req.body.institution_id||old.institution_id);if(req.admin.role==='office_staff'&&institutionId!==req.admin.institution_id)return res.status(403).json({error:'Forbidden'});const key=String(req.body.service_key||old.service_key).trim().toLowerCase().replace(/[^a-z0-9_-]/g,'-');db.prepare('UPDATE office_services SET institution_id=?,service_key=?,name_am=?,name_en=?,description_am=?,description_en=?,fee=?,currency=?,estimated_days=?,required_documents=?,form_schema=?,workflow_schema=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(institutionId,key,String(req.body.name_am||''),String(req.body.name_en||''),String(req.body.description_am||''),String(req.body.description_en||''),Math.max(0,Number(req.body.fee||0)),String(req.body.currency||'ETB').slice(0,8),Math.max(0,Number(req.body.estimated_days||3)),String(req.body.required_documents||'').slice(0,1000),JSON.stringify(safeSchema(req.body.form_schema)),JSON.stringify(safeWorkflow(req.body.workflow_schema)),req.body.active===0?0:1,req.params.id);res.json({ok:true});});
