app.get('/api/admin/service-requests/:id/workflow',auth,scopeRequests,(req,res)=>{const r=db.prepare('SELECT * FROM service_requests WHERE id=?').get(req.params.id);if(!r)return res.status(404).json({error:'Request not found'});if(req.officeScope&&r.assigned_institution_id!==req.officeScope)return res.status(403).json({error:'Forbidden'});const steps=workflowForRequest(r);const logs=db.prepare('SELECT * FROM service_workflow_logs WHERE request_id=? ORDER BY id').all(r.id);res.json({current_step_key:r.current_step_key||steps[0]?.key||'',steps,logs});});
app.put('/api/admin/service-requests/:id/workflow',auth,scopeRequests,(req,res)=>{const r=db.prepare('SELECT * FROM service_requests WHERE id=?').get(req.params.id);if(!r)return res.status(404).json({error:'Request not found'});if(req.officeScope&&r.assigned_institution_id!==req.officeScope)return res.status(403).json({error:'Forbidden'});const steps=workflowForRequest(r);const target=steps.find(x=>x.key===String(req.body.step_key||''));if(!target)return res.status(400).json({error:'የሂደት ደረጃ አልተገኘም።'});const note=String(req.body.note||'').slice(0,1000);db.prepare('UPDATE service_requests SET current_step_key=?,status=?,admin_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(target.key,target.status,note,r.id);db.prepare('INSERT INTO service_workflow_logs(request_id,step_key,step_name_am,step_name_en,action,actor,note) VALUES(?,?,?,?,?,?,?)').run(r.id,target.key,target.name_am,target.name_en,'transition',req.admin.email,note);db.prepare('INSERT INTO request_updates(request_id,status,note,actor) VALUES(?,?,?,?)').run(r.id,target.status,note,req.admin.email);if(r.status!==target.status&&r.citizen_id){db.prepare('INSERT INTO notifications(request_id,citizen_id,channel,recipient,message) VALUES(?,?,?,?,?)').run(r.id,r.citizen_id,'in-app',r.phone,`የጥያቄ ${r.reference_no} ሂደት: ${target.name_am} — ${target.status}`);}res.json({ok:true,current_step_key:target.key,status:target.status});});
app.post('/api/public/service-requests',requestLimiter,requestUpload.array('documents',5),async(req,res)=>{
 const serviceKey=String(req.body.service_key||'general'); const svc=getService(serviceKey);
 const fullName=String(req.body.full_name||'').trim(), phone=String(req.body.phone||'').trim(), details=String(req.body.details||'').trim();
 if(!svc||fullName.length<2||phone.length<7||details.length<5){for(const f of req.files||[])try{fs.unlinkSync(f.path)}catch{};return res.status(400).json({error:'እባክዎ የአገልግሎት፣ ሙሉ ስም፣ ስልክ እና ዝርዝር ጥያቄ በትክክል ይሙሉ።'});}
 if(svc.required_documents.length && !(req.files||[]).length){return res.status(400).json({error:`ለዚህ አገልግሎት የሚፈለጉ ሰነዶች፦ ${svc.required_documents.join(', ')}። ቢያንስ አንድ ሰነድ ያያይዙ።`});}
 const formData={}; for(const f of svc.form_schema){const v=String(req.body[f.name]||'').trim();if(f.required&&!v){for(const x of req.files||[])try{fs.unlinkSync(x.path)}catch{};return res.status(400).json({error:`${f.label_am} ያስፈልጋል።`});}if(v)formData[f.name]=v;}
 let ref; for(let i=0;i<5;i++){const candidate=makeRef(); if(!db.prepare('SELECT 1 FROM service_requests WHERE reference_no=?').get(candidate)){ref=candidate;break;}}
 if(!ref){for(const f of req.files||[])try{fs.unlinkSync(f.path)}catch{};return res.status(500).json({error:'Reference generation failed'});}
 const kebele=String(req.body.kebele||'').trim(); const citizenId=req.cookies.mesob_citizen ? (()=>{try{return jwt.verify(req.cookies.mesob_citizen,JWT_SECRET).id}catch{return null}})() : null;
 const due=new Date(Date.now()+svc.estimated_days*86400000).toISOString().slice(0,10);
 const tx=db.transaction(()=>{db.prepare('INSERT INTO service_requests(reference_no,service_key,service_name_am,service_name_en,full_name,phone,kebele,details,form_data,assigned_institution_id,citizen_id,due_date,current_step_key,workflow_schema_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(ref,serviceKey,svc.am,svc.en,fullName,phone,kebele,details,JSON.stringify(formData),svc.officeId,citizenId,due,svc.workflow_schema?.[0]?.key||'',JSON.stringify(svc.workflow_schema||[]));const requestId=db.prepare('SELECT id FROM service_requests WHERE reference_no=?').get(ref).id;for(const f of req.files||[])db.prepare('INSERT INTO service_request_documents(request_id,filename,original_name,mime_type,size) VALUES(?,?,?,?,?)').run(requestId,f.filename,f.originalname,f.mimetype,f.size);db.prepare('INSERT INTO request_updates(request_id,status,note,actor) VALUES(?,?,?,?)').run(requestId,'Received','ጥያቄው በድረ-ገጽ ተቀብሏል።','system');if(svc.fee>0)db.prepare('INSERT INTO payments(request_id,reference_no,provider,amount,currency,status) VALUES(?,?,?,?,?,?)').run(requestId,ref,process.env.PAYMENT_PROVIDER||'manual',svc.fee,svc.currency||process.env.PAYMENT_CURRENCY||'ETB','Pending');});
 try{tx()}catch(e){for(const f of req.files||[])try{fs.unlinkSync(f.path)}catch{};return res.status(500).json({error:'ጥያቄው ማስቀመጥ አልተቻለም።'});}
 const requestId=db.prepare('SELECT id FROM service_requests WHERE reference_no=?').get(ref).id; if(citizenId)queueCitizenNotifications(requestId,citizenId,phone,`የጥያቄ ${ref} ተቀብሏል።`);res.status(201).json({ok:true,reference_no:ref,message:`የ${svc.am} ጥያቄዎ ተቀብሏል። ማጣቀሻ ቁጥርዎ ${ref} ነው።`,payment_required:svc.payment_required,fee:svc.fee,currency:svc.currency,due_date:due});
});
app.get('/api/public/service-requests/status',(req,res)=>{const ref=String(req.query.reference_no||'').trim(),phone=String(req.query.phone||'').trim();if(!ref||!phone)return res.status(400).json({error:'Reference number and phone are required'});const r=db.prepare('SELECT r.reference_no,r.service_name_am,r.service_name_en,r.status,r.admin_note,r.priority,r.due_date,r.created_at,r.updated_at,i.name_am office_name_am,i.name_en office_name_en FROM service_requests r LEFT JOIN institutions i ON i.id=r.assigned_institution_id WHERE r.reference_no=? AND r.phone=?').get(ref,phone);if(!r)return res.status(404).json({error:'የጥያቄው መረጃ አልተገኘም።'});r.timeline=db.prepare('SELECT status,note,actor,created_at FROM request_updates WHERE request_id=(SELECT id FROM service_requests WHERE reference_no=? AND phone=?) ORDER BY id').all(ref,phone);res.json(r);});
app.get('/api/admin/service-requests',auth,scopeRequests,(req,res)=>{const status=String(req.query.status||'').trim();const office=Number(req.query.office||0);let q='SELECT r.*,i.name_am office_name_am,i.name_en office_name_en FROM service_requests r LEFT JOIN institutions i ON i.id=r.assigned_institution_id';const w=[],p=[];if(status){w.push('r.status=?');p.push(status)}if(office){w.push('r.assigned_institution_id=?');p.push(office)} if(req.officeScope){w.push('r.assigned_institution_id=?');p.push(req.officeScope)}if(w.length)q+=' WHERE '+w.join(' AND ');q+=' ORDER BY r.id DESC LIMIT 300';res.json(db.prepare(q).all(...p));});
