app.put('/api/admin/service-requests/:id',auth,scopeRequests,(req,res)=>{const allowed=new Set(['Received','In Review','In Progress','Completed','Rejected']);const status=String(req.body.status||'Received');if(!allowed.has(status))return res.status(400).json({error:'Invalid status'});const note=String(req.body.admin_note||'');const office=req.officeScope||Number(req.body.assigned_institution_id)||null;const priority=['Low','Normal','High','Urgent'].includes(String(req.body.priority))?String(req.body.priority):'Normal';const due=String(req.body.due_date||'');const old=db.prepare('SELECT * FROM service_requests WHERE id=?').get(req.params.id);if(!old)return res.status(404).json({error:'Not found'});if(req.officeScope && old.assigned_institution_id!==req.officeScope)return res.status(403).json({error:'ይህ ጥያቄ ለእርስዎ የተመደበ አይደለም።'});db.prepare('UPDATE service_requests SET status=?,admin_note=?,assigned_institution_id=?,priority=?,due_date=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(status,note,office,priority,due,req.params.id);if(old.status!==status||old.admin_note!==note||old.assigned_institution_id!==office)db.prepare('INSERT INTO request_updates(request_id,status,note,actor) VALUES(?,?,?,?)').run(req.params.id,status,note,req.admin.email);if(old.status!==status){const msg=`የጥያቄ ${old.reference_no} ሁኔታ: ${status}`;db.prepare('INSERT INTO notifications(request_id,citizen_id,channel,recipient,message) VALUES(?,?,?,?,?)').run(req.params.id,old.citizen_id,'in-app',old.phone,msg);}res.json({ok:true});});
