app.post('/api/public/payments/:id/initiate',citizenAuth,async(req,res)=>{const p=db.prepare('SELECT p.*,r.citizen_id,r.phone FROM payments p JOIN service_requests r ON r.id=p.request_id WHERE p.id=?').get(req.params.id);if(!p||p.citizen_id!==req.citizen.id)return res.status(404).json({error:'Payment not found'});if(p.amount<=0)return res.status(400).json({error:'No payment is required'});if(p.status==='Verified')return res.json(p);const provider=(process.env.PAYMENT_PROVIDER||'manual').toLowerCase();if(provider==='chapa'&&process.env.CHAPA_SECRET_KEY){try{const r=await fetch('https://api.chapa.co/v1/transaction/initialize',{method:'POST',headers:{Authorization:`Bearer ${process.env.CHAPA_SECRET_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({amount:String(p.amount),currency:p.currency,email:(db.prepare('SELECT email FROM citizens WHERE id=?').get(req.citizen.id)?.email||'enewari@example.com'),first_name:(db.prepare('SELECT full_name FROM citizens WHERE id=?').get(req.citizen.id)?.full_name||'Citizen').split(' ')[0],tx_ref:p.reference_no,callback_url:process.env.PAYMENT_CALLBACK_URL||'',return_url:process.env.PAYMENT_RETURN_URL||''})});const j=await r.json();if(r.ok&&j.status==='success'){db.prepare("UPDATE payments SET status='Initiated',checkout_url=?,provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(j.data?.checkout_url||'',j.data?.tx_ref||p.reference_no,p.id);return res.json(db.prepare('SELECT * FROM payments WHERE id=?').get(p.id));}}catch(e){console.error('payment provider error',e.message)}}res.json({id:p.id,reference_no:p.reference_no,amount:p.amount,currency:p.currency,status:'Pending',message:'የክፍያ አቅራቢ አልተዋቀረም። Admin እስኪያዋቅር ድረስ ክፍያ አይተገበርም።'});});
app.post('/api/payments/webhook',async(req,res)=>{const secret=process.env.PAYMENT_WEBHOOK_SECRET;if(!secret||req.get('x-payment-secret')!==secret)return res.status(401).json({error:'Unauthorized'});const ref=String(req.body.tx_ref||req.body.reference_no||'').trim(),status=String(req.body.status||'').toLowerCase();if(!ref)return res.status(400).json({error:'Reference required'});const p=db.prepare('SELECT * FROM payments WHERE reference_no=?').get(ref);if(!p)return res.status(404).json({error:'Payment not found'});const next=status==='success'||status==='paid'||status==='completed'?'Verified':status==='failed'?'Failed':p.status;db.prepare('UPDATE payments SET status=?,provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(next,String(req.body.provider_reference||req.body.transaction_id||''),p.id);res.json({ok:true,status:next});});
app.get('/api/admin/service-requests/:id/documents',auth,scopeRequests,(req,res)=>{const r=db.prepare('SELECT assigned_institution_id FROM service_requests WHERE id=?').get(req.params.id);if(!r)return res.status(404).json({error:'Request not found'});if(req.officeScope&&r.assigned_institution_id!==req.officeScope)return res.status(403).json({error:'Forbidden'});res.json(db.prepare('SELECT * FROM service_request_documents WHERE request_id=? ORDER BY id').all(req.params.id));});
app.get('/api/admin/payments',auth,requireRole('superadmin','admin','viewer','editor','office_staff'),(req,res)=>{const scope=req.admin.role==='office_staff'&&req.admin.institution_id;let q='SELECT p.*,r.service_name_am,r.phone,i.name_am office_name_am FROM payments p JOIN service_requests r ON r.id=p.request_id LEFT JOIN institutions i ON i.id=r.assigned_institution_id';const args=[];if(scope){q+=' WHERE r.assigned_institution_id=?';args.push(req.admin.institution_id)}q+=' ORDER BY p.id DESC LIMIT 300';res.json(db.prepare(q).all(...args));});
app.get('/api/admin/operations',auth,(req,res)=>{const status=String(req.query.status||'').trim();const priority=String(req.query.priority||'').trim();const office=Number(req.query.office||0);const q=String(req.query.q||'').trim();const where=['1=1'];const args=[];if(status){where.push('r.status=?');args.push(status)}if(priority){where.push('r.priority=?');args.push(priority)}if(office){where.push('r.assigned_institution_id=?');args.push(office)}if(req.admin.role==='office_staff'&&req.admin.institution_id){where.push('r.assigned_institution_id=?');args.push(req.admin.institution_id)}if(q){where.push('(r.reference_no LIKE ? OR r.full_name LIKE ? OR r.phone LIKE ? OR r.service_name_am LIKE ?)');const x='%'+q+'%';args.push(x,x,x,x)}const rows=db.prepare(`SELECT r.*,i.name_am office_name_am,i.name_en office_name_en,CASE WHEN r.due_date!='' AND r.status NOT IN ('Completed','Rejected') AND datetime(r.due_date)<datetime('now') THEN 1 ELSE 0 END overdue FROM service_requests r LEFT JOIN institutions i ON i.id=r.assigned_institution_id WHERE ${where.join(' AND ')} ORDER BY overdue DESC, CASE r.priority WHEN 'Urgent' THEN 1 WHEN 'High' THEN 2 WHEN 'Normal' THEN 3 ELSE 4 END, r.id DESC LIMIT 500`).all(...args);const summary={total:rows.length,overdue:rows.filter(x=>x.overdue).length,urgent:rows.filter(x=>x.priority==='Urgent'&&x.status!=='Completed'&&x.status!=='Rejected').length,inProgress:rows.filter(x=>['In Review','In Progress'].includes(x.status)).length};res.json({summary,rows});});
app.post('/api/admin/operations/bulk-assign',auth,requireRole('superadmin','admin'),(req,res)=>{const ids=Array.isArray(req.body.request_ids)?req.body.request_ids.map(Number).filter(Boolean):[];const office=Number(req.body.institution_id||0);if(!ids.length||!office)return res.status(400).json({error:'Requests and institution are required'});const tx=db.transaction(()=>{for(const id of ids){const old=db.prepare('SELECT * FROM service_requests WHERE id=?').get(id);if(!old)continue;db.prepare('UPDATE service_requests SET assigned_institution_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(office,id);if(old.assigned_institution_id!==office){db.prepare('INSERT INTO request_updates(request_id,status,note,actor) VALUES(?,?,?,?)').run(id,old.status,'የስራ ምደባ ተቀይሯል።',req.admin.email);}}});tx();res.json({ok:true,count:ids.length});});
app.get('/api/admin/stats',auth,(req,res)=>{const total=db.prepare('SELECT COUNT(*) c FROM service_requests').get().c;const received=db.prepare("SELECT COUNT(*) c FROM service_requests WHERE status='Received'").get().c;const progress=db.prepare("SELECT COUNT(*) c FROM service_requests WHERE status IN ('In Review','In Progress')").get().c;const completed=db.prepare("SELECT COUNT(*) c FROM service_requests WHERE status='Completed'").get().c;const rejected=db.prepare("SELECT COUNT(*) c FROM service_requests WHERE status='Rejected'").get().c;const offices=db.prepare('SELECT i.id,i.name_am,COUNT(r.id) count FROM institutions i LEFT JOIN service_requests r ON r.assigned_institution_id=i.id GROUP BY i.id ORDER BY count DESC,i.id').all();res.json({total,received,progress,completed,rejected,offices});});
