function localAnswer(q){const x=q.toLowerCase(); if(x.includes('ተቋም')||x.includes('institution')){return 'የእነዋሪ ከተማ አስተዳደር 12 ዋና ተቋማት አሉት። ከንቲባ ፅ/ቤት፣ ከተማና መሰረተልማት፣ መሬት፣ ኢንቨስትመንት፣ ገንዘብ፣ ሴቶች/ህፃናት/ወጣቶች፣ ስፖርት/ባህል/ቱሪዝም፣ ገቢዎች፣ ስራና ክህሎት፣ ንግድ፣ ምክር ቤት እና ፖሊስ ፅ/ቤት።'} if(x.includes('ግብር')||x.includes('tax')) return 'የግብርና ገቢ ጉዳዮች ከገቢዎች ፅ/ቤት ጋር ይያያዛሉ። የግል ግብር መጠን ወይም ዕዳ ለማየት የቀጥታ የገቢ ዳታቤዝ/API ግንኙነት ያስፈልጋል።'; if(x.includes('ውሃ')||x.includes('water')) return 'የእነዋሪ ከተማ የውሃ አገልግሎት ስርዓት የቀጥታ ዳታ እስካሁን አልተገናኘም። የአገልግሎት መመሪያ ካለ ከአስተዳደሩ ማረጋገጥ ያስፈልጋል።'; if(x.includes('ቅጣት')||x.includes('traffic')) return 'የትራፊክ ቅጣት መረጃ ከፖሊስ ፅ/ቤት ወይም ተዛማጅ የትራፊክ ስርዓት ጋር API ሲገናኝ በቀጥታ ይመጣል።'; return 'ጥያቄዎን ተቀብያለሁ። ይህ ስርዓት ከአስተዳደሩ ዳታቤዝ ጋር ሲገናኝ የተቋማት፣ ዜና፣ ሰነዶችና አገልግሎቶችን በቀጥታ ማፈላለግ ይችላል።';}
async function aiAnswer(message){
 const provider=(process.env.AI_PROVIDER||'local').toLowerCase();
 const context=db.prepare('SELECT name_am,name_en,description_am,description_en FROM institutions WHERE active=1').all().map(x=>`${x.name_am} / ${x.name_en}: ${x.description_am}`).join('\n');
 const system=`You are Digital Mesob AI for Enewari City Administration. Answer in Amharic unless the user asks English. Only state facts supported by the supplied city data; if not known, say so. Be concise and helpful. City institutions:\n${context}`;
 try{
  if(provider==='openai' && process.env.OPENAI_API_KEY){const {default:OpenAI}=await import('openai'); const client=new OpenAI({apiKey:process.env.OPENAI_API_KEY}); const r=await client.responses.create({model:process.env.OPENAI_MODEL||'gpt-6-luna',instructions:system,input:message}); return {text:r.output_text,provider:'openai'};}
  if(provider==='ollama'){const r=await fetch((process.env.OLLAMA_BASE_URL||'http://127.0.0.1:11434')+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:process.env.OLLAMA_MODEL||'gemma3:4b',stream:false,messages:[{role:'system',content:system},{role:'user',content:message}]})}); if(r.ok){const j=await r.json();return {text:j.message?.content||localAnswer(message),provider:'ollama'}}}
 }catch(e){console.error('AI error',e.message)}
 return {text:localAnswer(message),provider:'local'};
}
app.get('/api/public/service-requests/feedback', (req,res)=>{const reference_no=String(req.query.reference_no||'').trim();const phone=String(req.query.phone||'').trim();if(!reference_no||!phone)return res.status(400).json({error:'Reference Number እና ስልክ ያስፈልጋሉ።'});const r=db.prepare('SELECT id,reference_no,status,full_name,citizen_id FROM service_requests WHERE reference_no=? AND phone=?').get(reference_no,phone);if(!r)return res.status(404).json({error:'የጥያቄው መረጃ አልተገኘም።'});if(r.status!=='Completed')return res.status(400).json({error:'አስተያየት መስጠት የሚችሉት ጥያቄው ከተጠናቀቀ በኋላ ነው።'});const f=db.prepare('SELECT rating,comment,created_at FROM service_feedback WHERE request_id=?').get(r.id);res.json({eligible:true,reference_no:r.reference_no,feedback:f||null});});
app.post('/api/public/service-requests/feedback', (req,res)=>{const reference_no=String(req.body.reference_no||'').trim();const phone=String(req.body.phone||'').trim();const rating=Number(req.body.rating);const comment=String(req.body.comment||'').trim().slice(0,1000);if(!reference_no||!phone||![1,2,3,4,5].includes(rating))return res.status(400).json({error:'Reference, ስልክ እና 1–5 ደረጃ ያስፈልጋሉ።'});const r=db.prepare('SELECT id,reference_no,status,citizen_id FROM service_requests WHERE reference_no=? AND phone=?').get(reference_no,phone);if(!r)return res.status(404).json({error:'የጥያቄው መረጃ አልተገኘም።'});if(r.status!=='Completed')return res.status(400).json({error:'ጥያቄው ገና አልተጠናቀቀም።'});const old=db.prepare('SELECT id FROM service_feedback WHERE request_id=?').get(r.id);if(old){db.prepare('UPDATE service_feedback SET rating=?,comment=?,updated_at=CURRENT_TIMESTAMP WHERE request_id=?').run(rating,comment,r.id);}else{db.prepare('INSERT INTO service_feedback(request_id,citizen_id,reference_no,rating,comment) VALUES(?,?,?,?,?)').run(r.id,r.citizen_id||null,r.reference_no,rating,comment);}res.json({ok:true,message:'አስተያየትዎ ተቀብሏል። እናመሰግናለን!'});});

app.get('/api/admin/notification-status',auth,requireRole('superadmin','admin'),(req,res)=>res.json({config:notificationConfig(),queued:db.prepare("SELECT COUNT(*) c FROM notifications WHERE status='Queued' AND channel!='in-app'").get().c,failed:db.prepare("SELECT COUNT(*) c FROM notifications WHERE status='Failed'").get().c,sent:db.prepare("SELECT COUNT(*) c FROM notifications WHERE status='Sent'").get().c}));
app.get('/api/admin/reports',auth,requireRole('superadmin','admin','viewer','editor','office_staff'),(req,res)=>{const scope=req.admin.role==='office_staff'&&req.admin.institution_id?req.admin.institution_id:null;const where=scope?' WHERE assigned_institution_id=?':'';const args=scope?[scope]:[];const total=db.prepare(`SELECT COUNT(*) c FROM service_requests${where}`).get(...args).c;const byStatus=db.prepare(`SELECT status,COUNT(*) c FROM service_requests${where} GROUP BY status ORDER BY c DESC`).all(...args);const byPriority=db.prepare(`SELECT priority,COUNT(*) c FROM service_requests${where} GROUP BY priority ORDER BY c DESC`).all(...args);const byOffice=db.prepare('SELECT i.name_am,COUNT(r.id) c FROM institutions i LEFT JOIN service_requests r ON r.assigned_institution_id=i.id GROUP BY i.id ORDER BY c DESC').all();const monthly=db.prepare(`SELECT substr(created_at,1,7) month,COUNT(*) c FROM service_requests${where} GROUP BY month ORDER BY month DESC LIMIT 12`).all(...args);const avg=db.prepare(`SELECT ROUND(AVG((julianday(updated_at)-julianday(created_at))*24),1) hours FROM service_requests WHERE status='Completed'${scope?' AND assigned_institution_id=?':''}`).get(...args).hours;res.json({total,byStatus,byPriority,byOffice,monthly,avgCompletionHours:avg});});
app.get('/api/admin/reports/export.csv',auth,requireRole('superadmin','admin','viewer','editor','office_staff'),(req,res)=>{const scope=req.admin.role==='office_staff'&&req.admin.institution_id?req.admin.institution_id:null;const where=scope?' WHERE r.assigned_institution_id=?':'';const args=scope?[scope]:[];const rows=db.prepare(`SELECT r.reference_no AS reference,r.status,r.priority,r.created_at,r.updated_at,i.name_am AS institution FROM service_requests r LEFT JOIN institutions i ON i.id=r.assigned_institution_id${where} ORDER BY r.created_at DESC`).all(...args);const escCsv=v=>`"${String(v??'').replace(/"/g,'""')}"`;const csv=['Reference,Status,Priority,Created At,Updated At,Institution',...rows.map(x=>[x.reference,x.status,x.priority,x.created_at,x.updated_at,x.institution].map(escCsv).join(','))].join('\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="enewari-service-report.csv"');res.send('\ufeff'+csv);});

app.get('/api/admin/feedback',auth,requireRole('superadmin','admin','viewer','editor'),(req,res)=>{const rows=db.prepare('SELECT f.*,r.service_name_am,r.full_name,i.name_am institution_name_am FROM service_feedback f JOIN service_requests r ON r.id=f.request_id LEFT JOIN institutions i ON i.id=r.assigned_institution_id ORDER BY f.id DESC LIMIT 500').all();const summary=db.prepare('SELECT COUNT(*) total,ROUND(AVG(rating),2) average,SUM(CASE WHEN rating=5 THEN 1 ELSE 0 END) five_star,SUM(CASE WHEN rating<=2 THEN 1 ELSE 0 END) low_rating FROM service_feedback').get();res.json({rows,summary});});

